const OPEN_COLUMNS = ['ID', 'Status', 'Goal', 'Done when', 'Owner', 'Next verification', 'Evidence'];
const PROPOSAL_COLUMNS = ['Proposal', 'By', 'Date', 'Why'];
const DONE_COLUMNS = ['ID', 'Status', 'Goal', 'Closed', 'Criteria met', 'Evidence'];
const BATON_COLUMNS = ['Order', 'Task', 'Start files', 'Done when', 'Verification command', 'Notes / blockers'];

function splitTableRow(line        )                  {
  const trimmed = line.trim();
  if (!trimmed.includes('|')) return null;
  const cells = trimmed.split(/(?<!\\)\|/);
  if (cells.length <= 1) return null;
  if (cells[0].trim() === '') cells.shift();
  if (cells.length > 0 && cells[cells.length - 1].trim() === '') cells.pop();
  return cells.map((c) => c.trim());
}

function isDelimiterRow(cells          )          {
  return cells.length > 0 && cells.every((c) => /^:?-{3,}:?$/.test(c.trim()));
}

function escapeTableCell(cell        )         {
  return cell.replace(/\r?\n/g, ' ').replace(/(?<!\\)\|/g, '\\|');
}

function findSectionLines(
  lines          ,
  marker        ,
  heading        
)                                                                 {
  const markerToken = `<!-- wiki:${marker} -->`;
  let startIdx = lines.findIndex((l) => l.trim() === markerToken);
  if (startIdx === -1) {
    startIdx = lines.findIndex((l) => l.trim().toLowerCase() === `## ${heading}`.toLowerCase());
  }
  if (startIdx === -1) {
    return null;
  }
  let endIdx = lines.findIndex((l, i) => i > startIdx && l.trim().startsWith('## '));
  if (endIdx === -1) {
    endIdx = lines.length;
  }
  return {
    startLine: startIdx,
    endLine: endIdx,
    lines: lines.slice(startIdx, endIdx),
  };
}

                                 
                   
                   
                           
                             
 

function extractTableFromLines(lines          )                        {
  const parsedRows                                             = [];
  for (let i = 0; i < lines.length; i++) {
    const cells = splitTableRow(lines[i]);
    if (cells) {
      parsedRows.push({ offset: i, cells });
    }
  }

  if (parsedRows.length < 2) return null;

  let headerIndex = -1;
  for (let i = 0; i < parsedRows.length - 1; i++) {
    if (
      parsedRows[i + 1].offset === parsedRows[i].offset + 1 &&
      isDelimiterRow(parsedRows[i + 1].cells) &&
      parsedRows[i + 1].cells.length === parsedRows[i].cells.length
    ) {
      headerIndex = i;
      break;
    }
  }

  if (headerIndex === -1) return null;

  const headerRow = parsedRows[headerIndex];
  const header = headerRow.cells;
  const headerOffset = headerRow.offset;

  let endOffset = lines.length;
  for (let i = headerOffset + 2; i < lines.length; i++) {
    if (!lines[i].trim()) {
      endOffset = i;
      break;
    }
  }

  const dataRows             = [];
  let tableEndLineOffset = headerOffset + 2;

  for (let i = headerIndex + 2; i < parsedRows.length; i++) {
    const r = parsedRows[i];
    if (r.offset >= endOffset) break;
    dataRows.push(r.cells);
    tableEndLineOffset = r.offset + 1;
  }

  return {
    header,
    rows: dataRows,
    headerLineOffset: headerOffset,
    tableEndLineOffset,
  };
}

function parseTrackerMarkdown(markdown        )              {
  const normalized = markdown.replace(/\r\n/g, '\n');
  const lines = normalized.split('\n');

  const openRows                   = [];
  const proposalRows                       = [];
  const doneRows                   = [];

  // 1. Open
  const openSection = findSectionLines(lines, 'open', 'Open');
  if (openSection) {
    const table = extractTableFromLines(openSection.lines);
    if (table) {
      const { header, rows } = table;
      const lowerHeader = header.map((h) => h.toLowerCase());
      const hasNamed = OPEN_COLUMNS.every((col) => lowerHeader.includes(col.toLowerCase()));

      const idIdx = hasNamed ? lowerHeader.indexOf('id') : 0;
      const statusIdx = hasNamed ? lowerHeader.indexOf('status') : 1;
      const goalIdx = hasNamed ? lowerHeader.indexOf('goal') : 2;
      const doneWhenIdx = hasNamed ? lowerHeader.indexOf('done when') : 3;
      const ownerIdx = hasNamed ? lowerHeader.indexOf('owner') : 4;
      const nextVerificationIdx = hasNamed ? lowerHeader.indexOf('next verification') : 5;
      const evidenceIdx = hasNamed ? lowerHeader.indexOf('evidence') : 6;

      for (const row of rows) {
        const id = (row[idIdx] || '').trim();
        const status = (row[statusIdx] || '⚪').trim()      ﻿            ﻿ ;
        const goal = (row[goalIdx] || '').trim();
        const doneWhen = (row[doneWhenIdx] || '').trim();
        const owner = (row[ownerIdx] || '').trim();
        const nextVerification = (row[nextVerificationIdx] || '').trim();
        const evidence = (row[evidenceIdx] || '').trim();

        if (id) {
          openRows.push({ id, status, goal, doneWhen, owner, nextVerification, evidence });
        }
      }
    }
  }

  // 2. Proposals
  const proposalSection = findSectionLines(lines, 'proposals', 'Proposals');
  if (proposalSection) {
    const table = extractTableFromLines(proposalSection.lines);
    if (table) {
      const { header, rows } = table;
      const lowerHeader = header.map((h) => h.toLowerCase());
      const hasNamed = PROPOSAL_COLUMNS.every((col) => lowerHeader.includes(col.toLowerCase()));

      const proposalIdx = hasNamed ? lowerHeader.indexOf('proposal') : 0;
      const byIdx = hasNamed ? lowerHeader.indexOf('by') : 1;
      const dateIdx = hasNamed ? lowerHeader.indexOf('date') : 2;
      const whyIdx = hasNamed ? lowerHeader.indexOf('why') : 3;

      for (const row of rows) {
        const proposal = (row[proposalIdx] || '').trim();
        const by = (row[byIdx] || '').trim();
        const date = (row[dateIdx] || '').trim();
        const why = (row[whyIdx] || '').trim();

        if (proposal) {
          proposalRows.push({ proposal, by, date, why });
        }
      }
    }
  }

  // 3. Done
  const doneSection = findSectionLines(lines, 'done', 'Done');
  if (doneSection) {
    const table = extractTableFromLines(doneSection.lines);
    if (table) {
      const { header, rows } = table;
      const lowerHeader = header.map((h) => h.toLowerCase());
      const hasNamed = DONE_COLUMNS.every((col) => lowerHeader.includes(col.toLowerCase()));
      const isLegacy5 = !lowerHeader.includes('status') && header.length === 5;

      let idIdx = 0;
      let statusIdx = 1;
      let goalIdx = 2;
      let closedIdx = 3;
      let criteriaMetIdx = 4;
      let evidenceIdx = 5;

      if (hasNamed) {
        idIdx = lowerHeader.indexOf('id');
        statusIdx = lowerHeader.indexOf('status');
        goalIdx = lowerHeader.indexOf('goal');
        closedIdx = lowerHeader.indexOf('closed');
        criteriaMetIdx = lowerHeader.indexOf('criteria met');
        evidenceIdx = lowerHeader.indexOf('evidence');
      } else if (isLegacy5) {
        idIdx = 0;
        statusIdx = -1;
        goalIdx = 1;
        closedIdx = 2;
        criteriaMetIdx = 3;
        evidenceIdx = 4;
      }

      for (const row of rows) {
        const id = (row[idIdx] || '').trim();
        const status = (statusIdx === -1 ? '🟢' : (row[statusIdx] || '🟢').trim())      ﻿       ;
        const goal = (row[goalIdx] || '').trim();
        const closed = (row[closedIdx] || '').trim();
        const criteriaMet = (row[criteriaMetIdx] || '').trim();
        const evidence = (row[evidenceIdx] || '').trim();

        if (id) {
          doneRows.push({ id, status, goal, closed, criteriaMet, evidence });
        }
      }
    }
  }

  return {
    open: openRows,
    proposals: proposalRows,
    done: doneRows,
  };
}

function parseHandoffMarkdown(markdown        )              {
  const normalized = markdown.replace(/\r\n/g, '\n');
  const lines = normalized.split('\n');

  // State bullets
  const stateBullets                         = {};
  const stateSection = findSectionLines(lines, 'state', 'Current Work State');
  if (stateSection) {
    for (const line of stateSection.lines) {
      const match = line.match(/^\s*-\s+([^:]+):\s*(.*)$/);
      if (match) {
        stateBullets[match[1].trim()] = match[2].trim();
      }
    }
  }

  // Baton
  const baton             = [];
  let noOpenWork = false;
  const batonSection = findSectionLines(lines, 'baton', 'Baton For Next Coding Agent');
  if (batonSection) {
    for (const line of batonSection.lines) {
      if (line.trim().toLowerCase() === 'no open work.') {
        noOpenWork = true;
      }
    }

    const table = extractTableFromLines(batonSection.lines);
    if (table) {
      const { header, rows } = table;
      const lowerHeader = header.map((h) => h.toLowerCase());
      const hasNamed = BATON_COLUMNS.every((col) => lowerHeader.includes(col.toLowerCase()));

      const orderIdx = hasNamed ? lowerHeader.indexOf('order') : 0;
      const taskIdx = hasNamed ? lowerHeader.indexOf('task') : 1;
      const startFilesIdx = hasNamed ? lowerHeader.indexOf('start files') : 2;
      const doneWhenIdx = hasNamed ? lowerHeader.indexOf('done when') : 3;
      const verificationCommandIdx = hasNamed ? lowerHeader.indexOf('verification command') : 4;
      const notesIdx = hasNamed
        ? lowerHeader.indexOf('notes / blockers') !== -1
          ? lowerHeader.indexOf('notes / blockers')
          : lowerHeader.indexOf('notes')
        : 5;

      for (const row of rows) {
        const order = (row[orderIdx] || '').trim();
        const task = (row[taskIdx] || '').trim();
        const startFiles = (row[startFilesIdx] || '').trim();
        const doneWhen = (row[doneWhenIdx] || '').trim();
        const verificationCommand = (row[verificationCommandIdx] || '').trim();
        const notes = (row[notesIdx] || '').trim();

        if (order || task) {
          baton.push({ order, task, startFiles, doneWhen, verificationCommand, notes });
        }
      }
    }
  }

  // Blockers
  const blockers                                = [];
  const blockersSection = findSectionLines(lines, 'blockers', 'Blockers');
  if (blockersSection) {
    const table = extractTableFromLines(blockersSection.lines);
    if (table) {
      const { header, rows } = table;
      for (const row of rows) {
        const item                         = {};
        for (let i = 0; i < header.length; i++) {
          item[header[i]] = (row[i] || '').trim();
        }
        blockers.push(item);
      }
    }
  }

  return {
    stateBullets,
    baton,
    noOpenWork,
    blockers,
  };
}

function computeNextTrackerId(trackerMarkdown        , logMarkdown        )         {
  let maxId = 0;
  const regex = /\bT([1-9]\d*)\b/g;

  for (const text of [trackerMarkdown, logMarkdown]) {
    if (!text) continue;
    let match                        ;
    while ((match = regex.exec(text)) !== null) {
      const num = parseInt(match[1], 10);
      if (num > maxId) {
        maxId = num;
      }
    }
  }

  return `T${maxId + 1}`;
}

function formatTrackerOpenTable(rows                  , customHeader           )         {
  const header = customHeader && customHeader.length === OPEN_COLUMNS.length ? customHeader : OPEN_COLUMNS;
  const lines           = [
    `| ${header.join(' | ')} |`,
    `| ${header.map(() => '---').join(' | ')} |`,
  ];
  for (const r of rows) {
    lines.push(
      `| ${escapeTableCell(r.id)} | ${escapeTableCell(r.status)} | ${escapeTableCell(r.goal)} | ${escapeTableCell(r.doneWhen)} | ${escapeTableCell(r.owner)} | ${escapeTableCell(r.nextVerification)} | ${escapeTableCell(r.evidence)} |`
    );
  }
  return lines.join('\n');
}

function formatTrackerProposalTable(rows                      , customHeader           )         {
  const header = customHeader && customHeader.length === PROPOSAL_COLUMNS.length ? customHeader : PROPOSAL_COLUMNS;
  const lines           = [
    `| ${header.join(' | ')} |`,
    `| ${header.map(() => '---').join(' | ')} |`,
  ];
  for (const r of rows) {
    lines.push(
      `| ${escapeTableCell(r.proposal)} | ${escapeTableCell(r.by)} | ${escapeTableCell(r.date)} | ${escapeTableCell(r.why)} |`
    );
  }
  return lines.join('\n');
}

function formatTrackerDoneTable(rows                  , customHeader           )         {
  const header = customHeader && customHeader.length === DONE_COLUMNS.length ? customHeader : DONE_COLUMNS;
  const lines           = [
    `| ${header.join(' | ')} |`,
    `| ${header.map(() => '---').join(' | ')} |`,
  ];
  for (const r of rows) {
    lines.push(
      `| ${escapeTableCell(r.id)} | ${escapeTableCell(r.status)} | ${escapeTableCell(r.goal)} | ${escapeTableCell(r.closed)} | ${escapeTableCell(r.criteriaMet)} | ${escapeTableCell(r.evidence)} |`
    );
  }
  return lines.join('\n');
}

function replaceSectionTable(
  markdown        ,
  marker        ,
  heading        ,
  newTableMarkdown        
)         {
  const normalized = markdown.replace(/\r\n/g, '\n');
  const lines = normalized.split('\n');

  const section = findSectionLines(lines, marker, heading);
  const newTableLines = newTableMarkdown.split('\n');

  if (!section) {
    // Append section at end
    const appendLines           = ['', `## ${heading}`, `<!-- wiki:${marker} -->`, '', ...newTableLines, ''];
    return lines.join('\n').trimEnd() + '\n' + appendLines.join('\n');
  }

  const existingTable = extractTableFromLines(section.lines);

  if (existingTable) {
    const absoluteHeaderLine = section.startLine + existingTable.headerLineOffset;
    const absoluteTableEndLine = section.startLine + existingTable.tableEndLineOffset;
    lines.splice(absoluteHeaderLine, absoluteTableEndLine - absoluteHeaderLine, ...newTableLines);
  } else {
    // Insert table after marker line (section.startLine)
    lines.splice(section.startLine + 1, 0, '', ...newTableLines, '');
  }

  return lines.join('\n');
}

// --- End: src/lib/markdown-tables.ts ---


// --- Start: src/lib/human-actions.ts ---


                                                                       

const DISALLOWED_ACTORS = new Set([
  'agent',
  'coding agent',
  'ai',
  'unknown',
  'pending',
  'todo',
  'tbd',
  'n/a',
  'na',
  'none',
]);

function validateHumanActor(person        )       {
  if (!person || typeof person !== 'string' || !person.trim()) {
    throw new Error('Human authority required: person must be a non-empty human name');
  }
  const trimmed = person.trim();
  if (/^<.*>$/.test(trimmed)) {
    throw new Error(`Human authority required: person cannot be a placeholder ('${trimmed}')`);
  }
  if (DISALLOWED_ACTORS.has(trimmed.toLowerCase())) {
    throw new Error(`Human authority required: '${trimmed}' is not an authorized human person`);
  }
}

function validateNotProvenReason(reason        )       {
  if (!reason || typeof reason !== 'string' || !reason.trim()) {
    throw new Error('Closure requires a non-empty notProvenReason');
  }
  const trimmed = reason.trim().replace(/^`+|`+$/g, '').trim();
  if (/^<.*>$/.test(trimmed)) {
    throw new Error(`notProvenReason cannot be a placeholder ('${trimmed}')`);
  }
  if (DISALLOWED_ACTORS.has(trimmed.toLowerCase())) {
    throw new Error(`notProvenReason cannot be '${trimmed}'`);
  }
}

function promoteProposalToOpen(params   
                          
                      
                        
                 
                
                   
                           
                  
                   
 )                                                                       {
  validateHumanActor(params.person);
  if (!params.owner || !params.owner.trim()) {
    throw new Error('owner must be specified');
  }
  if (!params.doneWhen || !params.doneWhen.trim()) {
    throw new Error('doneWhen must be specified');
  }
  if (!params.nextVerification || !params.nextVerification.trim()) {
    throw new Error('nextVerification must be specified');
  }

  const tracker = parseTrackerMarkdown(params.trackerMarkdown);
  if (params.proposalIndex < 0 || params.proposalIndex >= tracker.proposals.length) {
    throw new Error(
      `Proposal index ${params.proposalIndex} out of bounds (0-${tracker.proposals.length - 1})`
    );
  }

  const proposal = tracker.proposals[params.proposalIndex];
  const assignedId = computeNextTrackerId(params.trackerMarkdown, params.logMarkdown);

  const newOpenRow                 = {
    id: assignedId,
    status: '⚪',
    goal: proposal.proposal,
    doneWhen: params.doneWhen.trim(),
    owner: params.owner.trim(),
    nextVerification: params.nextVerification.trim(),
    evidence: `commit ${params.shortSha}`,
  };

  const updatedOpen = [...tracker.open, newOpenRow];
  const updatedProposals = tracker.proposals.filter((_, idx) => idx !== params.proposalIndex);

  let updatedTracker = replaceSectionTable(
    params.trackerMarkdown,
    'open',
    'Open',
    formatTrackerOpenTable(updatedOpen)
  );
  updatedTracker = replaceSectionTable(
    updatedTracker,
    'proposals',
    'Proposals',
    formatTrackerProposalTable(updatedProposals)
  );

  updatedTracker = updateFrontmatterFields(updatedTracker, {
    source_commit: params.shortSha,
    updated: params.dateIso,
  });

  const logEntry = [
    '',
    `## ${params.dateIso} · Promote proposal to ${assignedId} · human`,
    `- What: Promoted proposal "${proposal.proposal}" to ${assignedId}`,
    `- By: ${params.person}`,
    `- Owner: ${params.owner.trim()}`,
    `- Evidence: manual review @${params.shortSha}`,
    `- IDs: ${assignedId}`,
    '',
  ].join('\n');

  let updatedLog = params.logMarkdown.trimEnd() + '\n' + logEntry;
  updatedLog = updateFrontmatterFields(updatedLog, {
    source_commit: params.shortSha,
    updated: params.dateIso,
  });

  return {
    trackerMarkdown: updatedTracker,
    logMarkdown: updatedLog,
    assignedId,
  };
}

function closeTrackerItemHumanUnproven(params   
                          
                      
                 
                 
                          
                  
                   
 )                                                   {
  validateHumanActor(params.person);
  validateNotProvenReason(params.notProvenReason);

  const tracker = parseTrackerMarkdown(params.trackerMarkdown);
  const openIndex = tracker.open.findIndex((r) => r.id === params.taskId);
  if (openIndex === -1) {
    throw new Error(`Task ${params.taskId} not found in open tracker`);
  }

  const openRow = tracker.open[openIndex];
  const updatedOpen = tracker.open.filter((_, idx) => idx !== openIndex);

  const cleanEvidence =
    openRow.evidence && !DISALLOWED_ACTORS.has(openRow.evidence.trim().toLowerCase())
      ? openRow.evidence
      : `manual review @${params.shortSha}`;

  const closedRow                 = {
    id: openRow.id,
    status: '⚫',
    goal: openRow.goal,
    closed: params.dateIso,
    criteriaMet: `closed by ${params.person} ${params.dateIso}; not proven: ${params.notProvenReason.trim()}`,
    evidence: cleanEvidence,
  };

  const updatedDone = [...tracker.done, closedRow];

  let updatedTracker = replaceSectionTable(
    params.trackerMarkdown,
    'open',
    'Open',
    formatTrackerOpenTable(updatedOpen)
  );
  updatedTracker = replaceSectionTable(
    updatedTracker,
    'done',
    'Done',
    formatTrackerDoneTable(updatedDone)
  );

  updatedTracker = updateFrontmatterFields(updatedTracker, {
    source_commit: params.shortSha,
    updated: params.dateIso,
  });

  const logEntry = [
    '',
    `## ${params.dateIso} · Close ${params.taskId} without proof · human`,
    `- What: Closed ${params.taskId} without proof (${params.notProvenReason.trim()})`,
    `- By: ${params.person}`,
    `- Evidence: manual review @${params.shortSha}`,
    `- IDs: ${params.taskId}`,
    '',
  ].join('\n');

  let updatedLog = params.logMarkdown.trimEnd() + '\n' + logEntry;
  updatedLog = updateFrontmatterFields(updatedLog, {
    source_commit: params.shortSha,
    updated: params.dateIso,
  });

  return {
    trackerMarkdown: updatedTracker,
    logMarkdown: updatedLog,
  };
}

function approveDecisionHuman(params   
                           
                      
                 
                       
                  
                   
 )                                                    {
  validateHumanActor(params.person);
  if (!params.whereContext || !params.whereContext.trim()) {
    throw new Error('whereContext must be specified');
  }

  const parsedDecision = parseFrontmatter(params.decisionMarkdown);
  let title = parsedDecision.fields['title'] || '';
  if (!title) {
    const headingMatch = parsedDecision.body.match(/^#\s+(.*)$/m);
    title = headingMatch ? headingMatch[1].trim() : 'Decision';
  }

  let updatedDecision = updateFrontmatterFields(params.decisionMarkdown, {
    status: 'accepted',
    source_commit: params.shortSha,
    updated: params.dateIso,
  });

  const approvalLine = `accepted: approved by ${params.person.trim()} (${params.whereContext.trim()}) on ${params.dateIso}.`;

  const lines = updatedDecision.replace(/\r\n/g, '\n').split('\n');
  const approvalIdx = lines.findIndex((l) => l.trim().toLowerCase() === '## approval');

  if (approvalIdx !== -1) {
    let nextHeadingIdx = lines.findIndex(
      (l, idx) => idx > approvalIdx && l.trim().startsWith('## ')
    );
    if (nextHeadingIdx === -1) {
      nextHeadingIdx = lines.length;
    }
    lines.splice(approvalIdx + 1, nextHeadingIdx - (approvalIdx + 1), approvalLine);
    updatedDecision = lines.join('\n');
  } else {
    updatedDecision = updatedDecision.trimEnd() + `\n\n## Approval\n${approvalLine}\n`;
  }

  const logEntry = [
    '',
    `## ${params.dateIso} · Approve decision ${title} · human`,
    `- What: Approved decision ${title}`,
    `- By: ${params.person} (${params.whereContext.trim()})`,
    `- Evidence: manual review @${params.shortSha}`,
    `- Decisions: ${title}`,
    '',
  ].join('\n');

  let updatedLog = params.logMarkdown.trimEnd() + '\n' + logEntry;
  updatedLog = updateFrontmatterFields(updatedLog, {
    source_commit: params.shortSha,
    updated: params.dateIso,
  });

  return {
    decisionMarkdown: updatedDecision,
    logMarkdown: updatedLog,
  };
}

// --- End: src/lib/human-actions.ts ---


try {
  const input = JSON.parse(fs.readFileSync(0, "utf-8"));
  let result;
  if (input.action === "promote-proposal") {
    result = promoteProposalToOpen(input);
  } else if (input.action === "close-unproven") {
    result = closeTrackerItemHumanUnproven(input);
  } else if (input.action === "approve-decision") {
    result = approveDecisionHuman(input);
  } else {
    throw new Error("Unknown action: " + input.action);
  }
  process.stdout.write(JSON.stringify(result));
} catch (err) {
  process.stderr.write(String(err.message || err));
  process.exit(1);
}
